    m = len(a)
    k = len(a[0])
    n = len(b[0])
    result = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            for l in range(k):
                result[i][j] += a[i][l] * b[l][j]
    return result
