def compress_string(s: str) -> str:
    if not s:
        return ""
    compressed = []
    count = 1
    prev_char = s[0]
    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            compressed.append(prev_char + str(count))
            prev_char = char
            count = 1
    compressed.append(prev_char + str(count))
    compressed_str = ''.join(compressed)
    return compressed_str if len(compressed_str) < len(s) else s

