def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [[(0, '') for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                current_lcs = a[i] + dp[i + 1][j + 1][1]
                if dp[i + 1][j + 1][0] + 1 > len(dp[i][j][1]):
                    dp[i][j] = (dp[i + 1][j + 1][0] + 1, current_lcs)
                elif dp[i + 1][j + 1][0] + 1 == len(dp[i][j][1]):
                    dp[i][j] = (dp[i + 1][j + 1][0] + 1, min(dp[i][j][1], current_lcs))
            else:
                if dp[i + 1][j][0] > dp[i][j + 1][0]:
                    dp[i][j] = dp[i + 1][j]
                elif dp[i + 1][j][0] == dp[i][j + 1][0]:
                    dp[i][j] = (dp[i + 1][j][0], min(dp[i + 1][j][1], dp[i][j + 1][1]))

    return dp[0][0][1]
