from typing import List

def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    if target == 0:
        return 0

    # Initialize a dynamic programming array
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for i in range(len(coins)):
        coin = coins[i]
        limit = limits[i]
        # Iterate backwards to avoid reusing the same coin multiple times in one iteration
        for j in range(target, -1, -1):
            for k in range(1, limit + 1):
                if j >= k * coin:
                    dp[j] = min(dp[j], dp[j - k * coin] + k)

    return dp[target] if dp[target] != float('inf') else -1
