def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set((r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n)

    def backtrack(row, cols, diag1, diag2):
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if col not in cols and (row - col) not in diag1 and (row + col) not in diag2:
                if (row, col) not in blocked_set:
                    count += backtrack(row + 1, cols | {col}, diag1 | {row - col}, diag2 | {row + col})
        return count

    return backtrack(0, set(), set(), set())
