def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set(blocked)
    rows = [False] * n
    cols = [False] * n
    diag1 = [False] * (2 * n - 1)
    diag2 = [False] * (2 * n - 1)

    def backtrack(row):
        if row == n:
            return 1
        total = 0
        for col in range(n):
            if (row, col) in blocked_set:
                continue
            if not rows[col] and not diag1[row - col + n - 1] and not diag2[row + col]:
                rows[col] = True
                diag1[row - col + n - 1] = True
                diag2[row + col] = True
                total += backtrack(row + 1)
                rows[col] = False
                diag1[row - col + n - 1] = False
                diag2[row + col] = False
        return total

    return backtrack(0)

