    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[[False] * (cols + 1) for _ in range(rows + 1)] for _ in range(2)]

    queue = deque()
