    visited[0][start[0]][start[1]] = True

    while queue:
        r, c, steps, walls = queue.popleft()

        if (r, c) == end:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    if walls < 1 and not visited[1][nr][nc]:
                        visited[1][nr][nc] = True
                        queue.append((nr, nc, steps + 1, walls + 1))
                else:
                    if not visited[0][nr][nc]:
                        visited[0][nr][nc] = True
                        queue.append((nr, nc, steps + 1, walls))

