def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    # Identity matrix
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    # Function to multiply two matrices under mod
    def multiply(a, b):
        return [
            [
                sum(a[i][k] * b[k][j] for k in range(n)) % mod
                for j in range(n)
            ]
            for i in range(n)
        ]

    # Function to square a matrix and return the result under mod
    def square(mat):
        return multiply(mat, mat)

    # Efficient exponentiation using binary exponentiation
    while exp > 0:
        if exp % 2 == 1:
            result = multiply(result, matrix)
        matrix = square(matrix)
        exp //= 2

    return result
