import re
import math

def evaluate_expression(expression: str) -> float:
    expression = expression.strip()
    if not expression:
        raise ValueError("Empty expression")

    # Check for balanced parentheses
    if expression.count('(') != expression.count(')'):
        raise ValueError("Unbalanced parentheses")

    # Check for invalid characters
    if re.search(r'[^0-9.+\-*/() ]', expression):
        raise ValueError("Invalid character in expression")

    # Replace spaces with nothing
    expression = expression.replace(' ', '')

    # Evaluate the expression using Python's eval function with safety checks
    try:
        # Replace ** with ** for Python's exponentiation
        expression = expression.replace('**', '**')
        # Replace unary minus with a negative number if it's at the start or after an operator or parenthesis
        expression = re.sub(r'(?<![\d\)])-(?=\d|\()', r'-', expression)
        result = eval(expression, {"__builtins__": None}, {"math": math})
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid expression") from e

