import re

def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')

    # Check local part
    if not re.fullmatch(r'[a-zA-Z0-9](?:[a-zA-Z0-9.-]*[a-zA-Z0-9])', local):
        return False

    # Check domain part
    if not re.fullmatch(r'[a-zA-Z0-9]+(\.[a-zA-Z0-9]+)+', domain):
        return False

    # Ensure the last label has at least two characters
    if len(domain.split('.')) == 1:
        return False
    last_label = domain.split('.')[-1]
    if len(last_label) < 2:
        return False

    return True
