def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            if i + 1 < len(encoded):
                char = encoded[i + 1]
                if i + 2 < len(encoded) and encoded[i + 2] == '~':
                    i += 3
                    n = 0
                    while i < len(encoded) and encoded[i].isdigit():
                        n = n * 10 + int(encoded[i])
                        i += 1
                    result.append(char * n)
                else:
                    result.append(char)
                    i += 2
            else:
                result.append('\\')
                i += 1
        else:
            result.append(encoded[i])
            i += 1
    return ''.join(result)
