def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    def backtrack(start, path, current_sum):
        if current_sum == k:
            result.append(path.copy())
            return
        if current_sum > k:
            return
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue
            if current_sum + nums[i] > k:
                break
            path.append(nums[i])
            backtrack(i + 1, path, current_sum + nums[i])
            path.pop()

    nums.sort()
    result = []
    backtrack(0, [], 0)
    return result
