def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for any item larger than capacity
    for size in sizes:
        if size > capacity:
            raise ValueError("All items must be smaller than or equal to capacity")

    # Sort sizes in descending order
    sizes.sort(reverse=True)

    # Initialize list of bins
    bins = []

    for size in sizes:
        placed = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
