import re
from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    # Check for invalid characters (control characters and space)
    if re.search(r'[\x00-\x1f\x7f \t\r\n]', target):
        return False

    # Check if target is a site-relative path (starts with / and next character is not /)
    if target.startswith('/') and len(target) > 1 and target[1] != '/':
        return True

    # Check if target starts with http:// or https:// and host matches
    url = urlparse(target)
    if url.scheme in ('http', 'https'):
        parsed_host = url.netloc
        if parsed_host and parsed_host.lower() == host.lower():
            return True

    return False

