from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    start_date = datetime.strptime(start, "%Y-%m-%d")
    holidays_set = set(datetime.strptime(h, "%Y-%m-%d") for h in holidays)

    days_added = 0
    current_date = start_date

    while days_added < abs(n):
        current_date += timedelta(days=1)
        if current_date.weekday() < 5 and current_date not in holidays_set:
            days_added += 1

    if n < 0:
        days_added = 0
        current_date = start_date
        while days_added < abs(n):
            current_date -= timedelta(days=1)
            if current_date.weekday() < 5 and current_date not in holidays_set:
                days_added += 1

    return current_date.strftime("%Y-%m-%d")
