def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]

    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    # Move 1 grain to each of the four neighbors
                    new_grid[r][c] -= 4
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            new_grid[nr][nc] += 1
                    changed = True

    return new_grid
