from math import gcd
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    def crt(c1, c2):
        r1, m1 = c1
        r2, m2 = c2
        g, x, y = extended_gcd(m1, m2)
        if (r2 - r1) % g != 0:
            return None
        lcm = m1 // g * m2
        r = (r1 + (r2 - r1) // g * x * m1) % lcm
        return (r, lcm)

    result = congruences[0]
    for congruence in congruences[1:]:
        result = crt(result, congruence)
        if result is None:
            return None
    return result
