import re
from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    # Check for invalid characters
    if any(c < 32 or c == 127 for c in target):
        return False

    # Check if target is a relative path starting with /
    if target.startswith('/') and len(target) > 1 and target[1] != '/':
        return True

    # Check if target is an absolute URL with matching host
    try:
        parsed = urlparse(target)
        if parsed.scheme not in ('http', 'https'):
            return False
        url_host = parsed.netloc
        if not url_host:
            return False
        return url_host.lower() == host.lower()
    except:
        return False
