def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    result = []

    def backtrack(start, path, current_sum):
        if current_sum == k:
            result.append(path.copy())
            return
        if current_sum > k:
            return
        for i in range(start, len(nums)):
            num = nums[i]
            if current_sum + num > k:
                continue
            path.append(num)
            backtrack(i + 1, path, current_sum + num)
            path.pop()

    backtrack(0, [], 0)
    return result
