import re

def is_local_redirect(target: str, host: str) -> bool:
    # Check for invalid characters (control characters and space)
    if re.search(r'[\x00-\x1f\x7f ]', target):
        return False

    # Check if target is a relative path starting with '/'
    if target.startswith('/') and (len(target) == 1 or target[1] != '/'):
        return True

    # Check if target is an absolute URL starting with http:// or https://
    if target.startswith('http://') or target.startswith('https://'):
        # Extract the host from the URL (ignoring user info and port)
        url = target.split('://')[1]
        if '/' in url:
            url = url.split('/', 1)[0]
        if url.lower() == host.lower():
            return True

    return False
```

