def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    while i < len(template):
        if template[i:i+2] == '{{':
            result.append('{')
            i += 2
        elif template[i:i+2] == '}}':
            result.append('}')
            i += 2
        elif template[i] == '{':
            # Find the nearest closing '}'
            j = i + 1
            while j < len(template) and template[j] != '}':
                j += 1
            if j < len(template):
                key = template[i+1:j]
                if key in values:
                    result.append(values[key])
                else:
                    result.append(template[i:j+1])
                i = j + 1
            else:
                # No closing '}' found, keep the '{'
                result.append('{')
                i += 1
        else:
            result.append(template[i])
            i += 1
    return ''.join(result)
