def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        raise ValueError
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    # Check if all characters are valid
    valid_chars = '0123456789abcdefghijklmnopqrstuvwxyz'
    for c in number:
        if c.lower() not in valid_chars:
            raise ValueError

    # Convert from base to decimal
    decimal_value = 0
    for c in number:
        digit = valid_chars.index(c.lower())
        decimal_value = decimal_value * from_base + digit

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert from decimal to target base
    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = valid_chars[remainder] + result
        decimal_value //= to_base

    # Apply negative sign if needed
    if is_negative:
        result = '-' + result

    return result
