from urllib.parse import urlparse

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    parsed = urlparse(url)
    scheme = parsed.scheme.lower()
    if scheme not in ('http', 'https'):
        return False

    netloc = parsed.netloc
    if '@' in netloc:
        return False

    host = netloc.split(':')[0].lower()
    if host.endswith('.'):
        host = host[:-1]

    allowed_hosts_lower = [h.lower() for h in allowed_hosts]

    for allowed_host in allowed_hosts_lower:
        if host == allowed_host:
            return True

    return False
