def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number:
        raise ValueError
    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if from_base > len(digits) or to_base > len(digits):
        raise ValueError

    # Convert number from from_base to decimal
    decimal_value = 0
    for ch in number:
        if ch.lower() not in digits[:from_base]:
            raise ValueError
        decimal_value = decimal_value * from_base + digits.index(ch.lower())

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert decimal to to_base
    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = digits[remainder] + result
        decimal_value //= to_base

    # Apply negative sign if needed
    if is_negative:
        result = '-' + result

    return result
