import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom function for sqrt, abs, sin, cos
    def custom_eval(node):
        if isinstance(node, ast.Expression):
            return custom_eval(node.body)
        elif isinstance(node, ast.UnaryOp):
            op = node.op
            if isinstance(op, ast.USub):
                return -custom_eval(node.operand)
            else:
                raise ValueError("Unsupported unary operation")
        elif isinstance(node, ast.BinOp):
            left = custom_eval(node.left)
            right = custom_eval(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            elif isinstance(op, ast.Sub):
                return left - right
            elif isinstance(op, ast.Mult):
                return left * right
            elif isinstance(op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                return left / right
            elif isinstance(op, ast.Pow):
                return left ** right
            else:
                raise ValueError("Unsupported binary operation")
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name):
                if func.id == 'sqrt':
                    if not isinstance(node.args[0], ast.Expression):
                        raise ValueError("Invalid argument for sqrt")
                    return math.sqrt(custom_eval(node.args[0]))
                elif func.id == 'abs':
                    if not isinstance(node.args[0], ast.Expression):
                        raise ValueError("Invalid argument for abs")
                    return abs(custom_eval(node.args[0]))
                elif func.id == 'sin':
                    if not isinstance(node.args[0], ast.Expression):
                        raise ValueError("Invalid argument for sin")
                    return math.sin(custom_eval(node.args[0]))
                elif func.id == 'cos':
                    if not isinstance(node.args[0], ast.Expression):
                        raise ValueError("Invalid argument for cos")
                    return math.cos(custom_eval(node.args[0]))
                else:
                    raise ValueError(f"Unknown function: {func.id}")
            else:
                raise ValueError("Invalid function call")
        elif isinstance(node, ast.Num):
            return float(node.n)
        elif isinstance(node, ast.Name):
            if node.id == 'x':
                return x
            else:
                raise ValueError(f"Unknown variable: {node.id}")
        else:
            raise ValueError("Unsupported node type")

    try:
        # Parse the formula into an AST
        tree = ast.parse(formula, mode='eval')
        # Evaluate the AST
        result = custom_eval(tree)
        return float(result)
    except (SyntaxError, ValueError, ZeroDivisionError) as e:
        raise ValueError("Invalid formula") from e
