def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit descending, then by original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], x))

    # Track used slots
    used_slots = set()

    # Schedule each job
    for name, deadline, _ in sorted_jobs:
        # Find the latest available slot not exceeding the deadline
        for slot in range(deadline, 0, -1):
            if slot not in used_slots:
                used_slots.add(slot)
                break

    # Prepare result: list of job names sorted by slot number
    result = []
    for slot in sorted(used_slots):
        # Find the job assigned to this slot
        for name, deadline, _ in sorted_jobs:
            if slot <= deadline and slot in used_slots:
                result.append(name)
                break

    return result
