from jinja2 import Template

def render_greeting_card(template: str, recipient: str, sender: str) -> str:
    # Define supported filters and their corresponding functions
    filters = {
        'upper': str.upper,
        'lower': str.lower,
        'capitalize': str.capitalize
    }

    # Process the template to apply filters
    def apply_filters(value: str, filter_name: str) -> str:
        if filter_name in filters:
            return filters[filter_name](value)
        return value

    # Replace placeholders with actual values, applying filters if present
    def replace_placeholder(match):
        placeholder = match.group(1)
        # Check if there's a filter after the vertical bar
        if '|' in placeholder:
            var_name, filter_name = placeholder.split('|', 1)
            filter_name = filter_name.strip()
            value = apply_filters(globals()[var_name], filter_name)
        else:
            var_name = placeholder
            value = globals()[var_name]
        return value

    # Use regex to find all placeholders and replace them
    import re
    processed_template = re.sub(r'{{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*(?:\|\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*)?}}', replace_placeholder, template)

    return processed_template

