def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the variable name in the formula
    formula = formula.replace('x', 'var')

    # Define a function to replace function calls with their math equivalents
    def replace_functions(node):
        if isinstance(node, ast.Expression):
            return replace_functions(node.body)
        elif isinstance(node, ast.UnaryOp):
            return ast.UnaryOp(op=replace_functions(node.op), operand=replace_functions(node.operand))
        elif isinstance(node, ast.BinOp):
            return ast.BinOp(left=replace_functions(node.left), op=replace_functions(node.op), right=replace_functions(node.right))
        elif isinstance(node, ast.Compare):
            return ast.Compare(left=replace_functions(node.left), ops=[replace_functions(op) for op in node.ops], comparators=[replace_functions(comp) for comp in node.comparators])
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name):
                func_name = func.id
                if func_name == 'sqrt':
                    return ast.UnaryOp(op=ast.UAdd(), operand=ast.Call(func=ast.Name(id='math.sqrt', ctx=ast.Load()), args=[replace_functions(node.args[0])], ctx=ast.Load()))
                elif func_name == 'abs':
                    return ast.UnaryOp(op=ast.UAdd(), operand=ast.Call(func=ast.Name(id='math.abs', ctx=ast.Load()), args=[replace_functions(node.args[0])], ctx=ast.Load()))
                elif func_name == 'sin':
                    return ast.UnaryOp(op=ast.UAdd(), operand=ast.Call(func=ast.Name(id='math.sin', ctx=ast.Load()), args=[replace_functions(node.args[0])], ctx=ast.Load()))
                elif func_name == 'cos':
                    return ast.UnaryOp(op=ast.UAdd(), operand=ast.Call(func=ast.Name(id='math.cos', ctx=ast.Load()), args=[replace_functions(node.args[0])], ctx=ast.Load()))
                else:
                    raise ValueError("Invalid function name")
            else:
                raise ValueError("Invalid function call")
        elif isinstance(node, ast.Name):
            if node.id == 'var':
                return ast.Name(id='x', ctx=ast.Load())
            else:
                raise ValueError("Invalid variable name")
        elif isinstance(node, ast.Num):
            return node
        elif isinstance(node, ast.UnaryOp):
            return ast.UnaryOp(op=replace_functions(node.op), operand=replace_functions(node.operand))
        elif isinstance(node, ast.BinOp):
            return ast.BinOp(left=replace_functions(node.left), op=replace_functions(node.op), right=replace_functions(node.right))
        elif isinstance(node, ast.operator):
            return node
        elif isinstance(node, ast.cmpop):
            return node
        else:
            raise ValueError("Invalid node type")

    # Parse the formula into an AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Replace function calls and variable references
    try:
        new_tree = replace_functions(tree)
    except ValueError as e:
        raise ValueError(str(e))

    # Compile the AST into a code object and evaluate it
