import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Check for invalid characters or syntax
    if not re.fullmatch(r'[-+*/()^.\d\s\w]+', formula):
        raise ValueError("Invalid formula")

    # Replace 'sqrt' with 'math.sqrt', 'abs' with 'math.abs', 'sin' with 'math.sin', 'cos' with 'math.cos'
    formula = formula.replace('sqrt', 'math.sqrt').replace('abs', 'math.abs').replace('sin', 'math.sin').replace('cos', 'math.cos')

    # Try to evaluate the formula
    try:
        result = eval(formula, {"math": math})
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except (SyntaxError, NameError, TypeError):
        raise ValueError("Invalid formula")

