from collections import defaultdict, deque

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    prev = {node: None for node in graph}

    # Dijkstra's algorithm
    priority_queue = [(0, start)]
    while priority_queue:
        current_dist, u = min(priority_queue)
        priority_queue.remove((current_dist, u))
        if u == goal:
            break
        for v, weight in graph[u]:
            if dist[v] > current_dist + weight:
                dist[v] = current_dist + weight
                prev[v] = u
                priority_queue.append((dist[v], v))

    if dist[goal] == float('inf'):
        return None

    # Reconstruct path
    path = []
    current = goal
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()

    # If multiple paths have the same cost, choose lexicographically smallest
    # Find all paths with minimal cost
    min_cost = dist[goal]
    min_paths = []
    visited = set()
    queue = deque([(start, [start])])
    visited.add(start)

    while queue:
        node, path = queue.popleft()
        if node == goal:
            if len(path) == 1:
                min_paths.append(path)
            else:
                if dist[path[-1]] == min_cost:
                    min_paths.append(path)
        for neighbor, _ in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    # Find the lexicographically smallest path
    min_paths = [path for path in min_paths if len(path) == len(min_paths[0])]
    min_paths.sort()
    return (min_cost, min_paths[0])
