import math
import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the variable name in the AST
    formula = formula.replace('x', 'var')

    # Define a custom evaluation function for the AST
    def eval_node(node):
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.UnaryOp):
            op = node.op
            if isinstance(op, ast.USub):
                return -eval_node(node.operand)
            else:
                raise ValueError("Unsupported unary operation")
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            elif isinstance(op, ast.Sub):
                return left - right
            elif isinstance(op, ast.Mult):
                return left * right
            elif isinstance(op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                return left / right
            elif isinstance(op, ast.Pow):
                return left ** right
            else:
                raise ValueError("Unsupported binary operation")
        elif isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Name):
                func_name = func.id
                if func_name == 'sqrt':
                    arg = eval_node(node.args[0])
                    return math.sqrt(arg)
                elif func_name == 'abs':
                    arg = eval_node(node.args[0])
                    return abs(arg)
                elif func_name == 'sin':
                    arg = eval_node(node.args[0])
                    return math.sin(arg)
                elif func_name == 'cos':
                    arg = eval_node(node.args[0])
                    return math.cos(arg)
                else:
                    raise ValueError(f"Unknown function: {func_name}")
            else:
                raise ValueError("Unsupported function call")
        elif isinstance(node, ast.Name):
            if node.id == 'var':
                return x
            else:
                raise ValueError(f"Unknown variable: {node.id}")
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Compare):
            # Handle comparisons, but since we only need to evaluate expressions, we'll ignore them
            return eval_node(node.left)
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

    # Parse the formula into an AST
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula syntax")

    # Evaluate the AST
    try:
        result = eval_node(tree)
    except ZeroDivisionError as e:
        raise ZeroDivisionError("division by zero") from e
    except Exception as e:
        raise ValueError("Invalid formula") from e

    return float(result)
