import re
import ast

def evaluate_formula(formula: str, x: float) -> float:
    # Replace 'x' with the actual value
    formula = formula.replace('x', str(x))

    # Define a custom function for each allowed function
    def custom_sqrt(arg):
        return math.sqrt(arg)

    def custom_abs(arg):
        return abs(arg)

    def custom_sin(arg):
        return math.sin(arg)

    def custom_cos(arg):
        return math.cos(arg)

    # Replace the function names with their custom implementations
    formula = formula.replace('sqrt', 'custom_sqrt')
    formula = formula.replace('abs', 'custom_abs')
    formula = formula.replace('sin', 'custom_sin')
    formula = formula.replace('cos', 'custom_cos')

    # Check if the formula contains any invalid characters or names
    if re.search(r'[^0-9.+\-*/\(\)\sxa-zA-Z]', formula):
        raise ValueError("Invalid formula")

    # Check if the formula contains any invalid function names
    if re.search(r'\b(sin|cos|sqrt|abs)\b', formula):
        pass
    else:
        raise ValueError("Invalid formula")

    # Check if the formula contains any other variables
    if re.search(r'[a-zA-Z][^x]', formula):
        raise ValueError("Invalid formula")

    # Try to parse the formula as an AST
    try:
        ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid formula")

    # Evaluate the formula
    try:
        result = eval(formula, {"__builtins__": None}, {"custom_sqrt": custom_sqrt, "custom_abs": custom_abs, "custom_sin": custom_sin, "custom_cos": custom_cos})
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except Exception as e:
        raise ValueError("Invalid formula")

    return float(result)
