def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_row = []
        for i, (cell, align) in enumerate(zip(row, aligns)):
            width = col_widths[i]
            if align == 'l':
                formatted_cell = cell.ljust(width)
            elif align == 'r':
                formatted_cell = cell.rjust(width)
            elif align == 'c':
                formatted_cell = cell.center(width)
            else:
                raise ValueError(f"Invalid alignment: {align}")
            formatted_row.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_row))

    return "\n".join(formatted_rows)
