import re
import ipaddress

def is_public_ip(ip_str: str) -> bool:
    # Check if the input is a valid IPv4 or IPv6 address in standard text form
    if not re.fullmatch(r'(\d{1,3}\.){3}\d{1,3}|\[?[0-9a-fA-F:]+]?$', ip_str):
        return False

    try:
        # Try to parse as IPv4
        ip = ipaddress.IPv4Address(ip_str)
        # Check if it's a public IPv4 address
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation:
            return False
        # Check if it's in the shared address space 100.64.0.0/10
        if ip.network_address <= ipaddress.IPv4Network('100.64.0.0/10').broadcast_address:
            return False
        # Check if it's the IPv4 broadcast address
        if ip == ipaddress.IPv4Address('255.255.255.255'):
            return False
        return True
    except ipaddress.AddressValueError:
        # Try to parse as IPv6
        try:
            ip = ipaddress.IPv6Address(ip_str)
            # Check if it's a public IPv6 address
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation:
                return False
            # Check if it's an IPv4-mapped IPv6 address
            if ip.ipv4_mapped:
                return is_public_ip(str(ip.ipv4_mapped))
            return True
        except ipaddress.AddressValueError:
            return False
