def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Determine column widths
    col_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Format each row
    formatted_rows = []
    for row in rows:
        line = []
        for i, cell in enumerate(row):
            width = col_widths[i]
            pad = width - len(cell)
            if aligns[i] == 'l':
                line.append(cell.ljust(width))
            elif aligns[i] == 'r':
                line.append(cell.rjust(width))
            elif aligns[i] == 'c':
                line.append(cell.center(width))
        formatted_rows.append(" | ".join(line))

    return "\n".join(formatted_rows)
