def is_public_ip(ip_str: str) -> bool:
    # Check if the input is a valid IPv4 or IPv6 address
    if not re.fullmatch(r'(\d{1,3}\.){3}\d{1,3}|([0-9a-fA-F:]+)', ip_str):
        return False

    try:
        # Try to parse as IPv4
        ip = ipaddress.IPv4Address(ip_str)
        # Check if it's a public IPv4 address
        return not (ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved or ip.is_documented or ip.is_broadcast or ip in ipaddress.ip_network('100.64.0.0/10'))
    except ipaddress.AddressValueError:
        pass

    try:
        # Try to parse as IPv6
        ip = ipaddress.IPv6Address(ip_str)
        # Check if it's a public IPv6 address
        return not (ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved or ip.is_documented)
    except ipaddress.AddressValueError:
        pass

    # Check for IPv4-mapped IPv6 address
