from collections import defaultdict, Counter

def top_k_elements(nums: list[int], k: int) -> list[int]:
    freq = defaultdict(int)
    first_occurrence = {}
    for idx, num in enumerate(nums):
        if num not in first_occurrence:
            first_occurrence[num] = idx
        freq[num] += 1

    # Sort by frequency (descending), then by first occurrence (ascending)
    sorted_nums = sorted(freq.keys(), key=lambda x: (-freq[x], first_occurrence[x]))

    return sorted_nums[:k]
