def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0
    instructions = {
        'PUSH': lambda x: stack.append(int(x)),
        'POP': lambda: stack.pop() if stack else None,
        'DUP': lambda: stack.append(stack[-1]) if stack else None,
        'SWAP': lambda: (stack[-1], stack[-2]) if len(stack) >= 2 else None,
        'ADD': lambda: (stack.pop(), stack.pop(), stack.append(stack.pop() + stack.pop())) if len(stack) >= 2 else None,
        'SUB': lambda: (stack.pop(), stack.pop(), stack.append(stack.pop() - stack.pop())) if len(stack) >= 2 else None,
        'MUL': lambda: (stack.pop(), stack.pop(), stack.append(stack.pop() * stack.pop())) if len(stack) >= 2 else None,
        'JMP': lambda t: (nonlocal pc, pc := int(t)) if t.isdigit() else None,
        'JZ': lambda t: (pc := int(t) if stack[-1] == 0 else pc + 1) if stack else None,
        'HALT': lambda: None
    }

    while 0 <= pc < len(program):
        if pc >= len(program):
