def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_queue = []

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            stock[item] = stock.get(item, 0) + quantity
            # Process waiting orders in the order they were received
            while waiting and stock[item] >= waiting[0][1]:
                order, qty = waiting.pop(0)
                order_queue.append((order, qty))
                stock[item] -= qty
        elif kind == 'order':
            waiting.append((item, quantity))

    # After processing all events, return the final stock and remaining waiting orders
    return stock, waiting
