                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif cmd.startswith("ADD"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif cmd.startswith("SUB"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
