def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    order_queue = {}  # Maps item to a list of (quantity, timestamp) tuples

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = stock.get(item, 0) + quantity
            # Process waiting orders for this item
            while order_queue.get(item, []) and stock[item] >= order_queue[item][0][0]:
                order = order_queue[item].pop(0)
                stock[item] -= order[0]
                waiting.append((item, order[0]))
        else:  # 'order'
            if item not in order_queue:
                order_queue[item] = []
            order_queue[item].append((quantity, len(events)))  # Use event index as timestamp

    # Convert waiting list to the required format
    waiting_list = [(item, qty) for item, (qty, _) in waiting]

    return (stock, waiting_list)
