                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith("ADD") or instruction.startswith("SUB") or instruction.startswith("MUL"):
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a, b = stack.pop(), stack.pop()
            if instruction == "ADD":
                stack.append(a + b)
            elif instruction == "SUB":
                stack.append(a - b)
            elif instruction == "MUL":
