def char_frequencies(text: str) -> dict[str, int]:
    """
    Returns a dictionary mapping each character in the input text to its frequency.
    Whitespace characters are ignored, and the count is case-sensitive.
    """
    frequencies = {}
    for char in text:
        if char.isspace():
            continue
        frequencies[char] = frequencies.get(char, 0) + 1
    return frequencies
