def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    # Create a copy of balances to modify
    final_balances = balances.copy()
    # Track frozen accounts
    frozen_accounts = set()
    # Track failed operations
    failed_ops = []

    for idx, op in enumerate(ops):
        if op[0] == 'deposit':
            account, amount = op[1], op[2]
            if account not in final_balances or amount <= 0 or account in frozen_accounts:
                failed_ops.append(idx)
                continue
            final_balances[account] += amount
        elif op[0] == 'withdraw':
            account, amount = op[1], op[2]
            if account not in final_balances or amount <= 0 or account in frozen_accounts:
                failed_ops.append(idx)
                continue
            if final_balances[account] < amount:
                failed_ops.append(idx)
                continue
            final_balances[account] -= amount
        elif op[0] == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if (source not in final_balances or target not in final_balances or
                amount <= 0 or source == target or source in frozen_accounts or target in frozen_accounts):
                failed_ops.append(idx)
                continue
            if final_balances[source] < amount + 2:
                failed_ops.append(idx)
                continue
            final_balances[source] -= amount + 2
            final_balances[target] += amount
        elif op[0] == 'freeze':
            account = op[1]
            if account not in final_balances:
                failed_ops.append(idx)
                continue
            if account not in frozen_accounts:
                frozen_accounts.add(account)
        elif op[0] == 'unfreeze':
            account = op[1]
            if account not in final_balances:
                failed_ops.append(idx)
                continue
            if account in frozen_accounts:
                frozen_accounts.remove(account)
        else:
            failed_ops.append(idx)

    return final_balances, sorted(failed_ops)
