    n = len(s)
    if n == 0:
        return 0
    lps = [0] * n
    length = 0
    for i in range(1, n):
        while length > 0 and s[i] != s[length]:
            length = lps[length - 1]
        if s[i] == s[length]:
            length += 1
            lps[i] = length
    return lps[-1]
