def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            n &= n - 1
            count += 1
        return count

    def count_set_bits_upto(n: int) -> int:
        if n == 0:
            return 0
        count = 0
        power = 1
        while power <= n:
            full_cycles = n // (power * 2)
            count += full_cycles * power
            remainder = n % (power * 2)
            count += max(0, remainder - power + 1)
            power *= 2
        return count

    return count_set_bits_upto(hi) - count_set_bits_upto(lo - 1)
