def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    n = len(coins)
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for i in range(n):
        coin = coins[i]
        limit = limits[i]
        for j in range(1, target + 1):
            for k in range(1, limit + 1):
                if j >= k * coin:
                    dp[j] = min(dp[j], dp[j - k * coin] + k)
                else:
                    break

    return dp[target] if dp[target] != float('inf') else -1
