def longest_bitonic_length(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    inc = [1] * n  # Longest increasing subsequence ending at i
    dec = [1] * n  # Longest decreasing subsequence starting at i

    # Compute increasing sequences
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute decreasing sequences
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[j] < nums[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum bitonic length
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - 1)

    return max_bitonic
