import xml.etree.ElementTree as ET

def count_items(xml_text: str) -> int:
    """Count the number of 'item' elements in an XML document."""
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return 0
    count = 0
    stack = [root]
    while stack:
        element = stack.pop()
        if element.tag == 'item':
            count += 1
        stack.extend(element)
    return count

