    while i < len(encoded):
        if encoded[i] == '\\':
            result.append(encoded[i + 1])
            i += 2
        elif encoded[i] in '~0123456789':
            # This case is handled by the ~ followed by a number
            # So we need to look for the ~ and the number
            # But since we are in a loop, we need to check if the current character is part of a ~n sequence
            # So we check if the current character is ~ and then look for the number
            if i + 1 < len(encoded) and encoded[i] == '~':
                # Find the end of the number
                j = i + 2
                while j < len(encoded) and encoded[j].isdigit():
                    j += 1
                # The number is from i+2 to j-1
                count = int(encoded[i+2:j])
                char = encoded[i - 1] if i > 0 else ''
                if char:
                    result.append(char * count)
                i = j
            else:
