from math import gcd
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            g, x, y = extended_gcd(b, a % b)
            return (g, y, x - (a // b) * y)

    def lcm(a, b):
        return a * b // gcd(a, b)

    def combine(a1, m1, a2, m2):
        g, x, y = extended_gcd(m1, m2)
        if (a2 - a1) % g != 0:
            return None
        lcm_mod = lcm(m1, m2)
        x0 = (a1 + (a2 - a1) // g * x * m1) % lcm_mod
        return (x0, lcm_mod)

    x, m = congruences[0]
    for r, mod in congruences[1:]:
        result = combine(x, m, r, mod)
        if result is None:
            return None
        x, m = result

    return (x, m)
