    # Check if target contains any invalid characters
    if any(c in r'\\ \t\n\r\v\f' for c in target):
        return False

    # Case 1: target is a site-relative path (starts with '/' and not a full path)
    if target.startswith('/') and len(target) > 1 and target[1] != '/':
        return True

    # Case 2: target starts with http:// or https:// and host matches
    url_match = re.match(r'^(https?:\/\/)?', target)
    if url_match:
        url = target.split('://', 1)[1]
        url_host = url.split('/', 1)[0]
        if url_host.lower() == host.lower():
            return True

    return False

