def convert_base(number: str, from_base: int, to_base: int) -> str:
    # Validate bases
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Bases must be between 2 and 36")

    # Validate number
    if not number:
        raise ValueError("Number cannot be empty")

    # Check if number is negative
    is_negative = number[0] == '-'
    if is_negative:
        number = number[1:]

    # Validate digits
    valid_digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    for ch in number:
        if ch.lower() not in valid_digits[:from_base]:
            raise ValueError("Invalid digit for the given base")

    # Convert from base from_base to base 10
    decimal_value = 0
    for ch in number:
        decimal_value = decimal_value * from_base + valid_digits.index(ch.lower())

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert from base 10 to base to_base
    if decimal_value < 0:
        decimal_value = -decimal_value
        is_negative = True

    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = valid_digits[remainder] + result
        decimal_value //= to_base

    # Apply negative sign if needed
    if is_negative:
        result = '-' + result

    return result

def convert_base(number: str, from_base: int, to_base: int) -> str:
    # Validate bases
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Bases must be between 2 and 36")

    # Validate number
    if not number:
        raise ValueError("Number cannot be empty")

    # Check if number is negative
    is_negative = number[0] == '-'
    if is_negative:
        number = number[1:]

    # Validate digits
    valid_digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    for ch in number:
        if ch.lower() not in valid_digits[:from_base]:
            raise ValueError("Invalid digit for the given base")

    # Convert from base from_base to base 10
    decimal_value = 0
    for ch in number:
        decimal_value = decimal_value * from_base + valid_digits.index(ch.lower())

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert from base 10 to base to_base
    if decimal_value < 0:
        decimal_value = -decimal_value
        is_negative = True

    result = ''
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = valid_digits[remainder] + result
        decimal_value //= to_base

    # Apply negative sign if needed
    if is_negative:
        result = '-' + result

    return result

