def tidy_punctuation(text: str) -> str:
    # Step 1: Replace runs of whitespace with a single space and strip leading/trailing spaces
    text = ' '.join(text.split())

    # Step 2: Remove spaces followed by one of the punctuation characters
    text = ''.join(char if not (char == ' ' and i + 1 < len(text) and text[i + 1] in {',', '.', ';', ':', '!', '?'}) else '' for i, char in enumerate(text))

    # Step 3: Insert a space after the punctuation characters if followed by a letter
    text = ''.join([char if i == 0 or i == len(text) - 1 or not (text[i] in {',', '.', ';', ':', '!', '?'} and text[i + 1].isalpha()) else char + ' ' if text[i + 1].isalpha() else char for i, char in enumerate(text)])

    # Step 4: Capitalize the first character and after . ! ?
    if not text:
        return text
    result = []
    i = 0
    while i < len(text):
        if i == 0 or (i > 0 and text[i - 1] in {'.', '!', '?'} and i < len(text) and text[i] == ' '):
            result.append(text[i].upper() if text[i].isalpha() else text[i])
            i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

