from typing import List, Tuple, Optional
import heapq

def cheapest_route(edges: List[Tuple[str, str, int]], start: str, goal: str) -> Optional[Tuple[int, List[str]]]:
    if start == goal:
        return (0, [start])

    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, w))
        graph[v].append((u, w))

    priority_queue = [(0, start, [start])]
    visited = set()

    while priority_queue:
        cost, current, path = heapq.heappop(priority_queue)
        if current in visited:
            continue
        visited.add(current)

        if current == goal:
            return (cost, path)

        for neighbor, weight in graph.get(current, []):
            if neighbor not in visited:
                new_path = path + [neighbor]
                new_cost = cost + weight
                heapq.heappush(priority_queue, (new_cost, neighbor, new_path))

    return None
