def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        c = source[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            # Parse number
            j = i
            while j < len(source) and (source[j].isdigit() or source[j] == '.'):
                j += 1
            if j - i == 0:
                raise ValueError("Invalid number")
            # Check if it's a valid number
            num_str = source[i:j]
            if '.' in num_str:
                if num_str.count('.') > 1:
                    raise ValueError("Invalid number")
                if not any(c.isdigit() for c in num_str.split('.')):
                    raise ValueError("Invalid number")
            tokens.append(("NUMBER", num_str))
            i = j
        elif c.isalpha() or c == '_':
            # Parse name
            j = i
            while j < len(source) and (source[j].isalnum() or source[j] == '_'):
                j += 1
            name_str = source[i:j]
            tokens.append(("NAME", name_str))
            i = j
        else:
            # Check for operators
            if i + 1 < len(source):
                op = source[i:i+2]
                if op in ('==', '!=', '<=', '>='):
                    tokens.append(("OP", op))
                    i += 2
                    continue
            # Check for single-character operators
            if c in '+-*/<>=()':
                tokens.append(("OP", c))
                i += 1
            elif c == '=':
                tokens.append(("OP", c))
                i += 1
            elif c == ',':
                tokens.append(("OP", c))
                i += 1
            else:
                raise ValueError(f"Invalid character: {c}")
    return tokens
