def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by descending profit, and then by original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], jobs.index(x)))
    slots = {}
    result = []

    for name, deadline, _ in sorted_jobs:
        if deadline < 1:
            continue
        # Find the highest-numbered available slot <= deadline
        slot = deadline
        while slot in slots:
            slot -= 1
        if slot >= 1:
            slots[slot] = name
            result.append(name)

    # Sort the result by slot number
    return [name for slot, name in sorted(slots.items())]
