            continue

        record = []
        j = 0
        while j < len(line):
            if line[j] == '"':
                # Start of a quoted field
                j += 1
                field = ''
                while j < len(line):
                    if line[j] == '"':
                        j += 1
                        if j < len(line) and line[j] == '"':
