from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find start and end positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return -1

    visited = [[False] * cols for _ in range(rows)]
    queue = deque([(start[0], start[1], 0)])
    visited[start[0]][start[1]] = True

    while queue:
        x, y, moves = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            # Check if the next cell is within bounds and not a wall
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                # Slide as far as possible in that direction
                while 0 <= nx + dx < rows and 0 <= ny + dy < cols and grid[nx + dx][ny + dy] != '#':
                    nx += dx
                    ny += dy
                # Check if the final position is the end
                if (nx, ny) == end:
                    return moves + 1
                # Check if the slide actually moved the puck
                if not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny, moves + 1))

    return -1
