def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    rings = []

    # Determine the rings
    for i in range((n + 1) // 2):
        ring = []
        # Top row
        for j in range(i, n - i):
            ring.append(matrix[i][j])
        # Right column (excluding top)
        for j in range(i + 1, n - i):
            ring.append(matrix[j][n - i - 1])
        # Bottom row (excluding right)
        if i != n - i - 1:
            for j in range(n - i - 2, i - 1, -1):
                ring.append(matrix[n - i - 1][j])
        # Left column (excluding bottom)
        if i != n - i - 1:
            for j in range(n - i - 2, i, -1):
                ring.append(matrix[j][i])
        rings.append(ring)

    # Rotate each ring
    for i in range(len(rings)):
        ring = rings[i]
        m = len(ring)
        if m == 0:
            continue
        k = k % m
        rotated_ring = ring[-k:] + ring[:-k]
        # Place the rotated ring back into the matrix
        idx = 0
        # Top row
        for j in range(i, n - i):
            result[i][j] = rotated_ring[idx]
            idx += 1
        # Right column (excluding top)
        for j in range(i + 1, n - i):
            result[j][n - i - 1] = rotated_ring[idx]
            idx += 1
        # Bottom row (excluding right)
        if i != n - i - 1:
            for j in range(n - i - 2, i - 1, -1):
