def evaluate_expression(expr: str) -> int:
    import re
    from collections import deque

    expr = expr.replace(' ', '')
    tokens = re.findall(r'(\d+|\+|\-|\*|/|\^|\(|\))', expr)

    def parse_expression(tokens):
        def parse_term(tokens):
            def parse_factor(tokens):
                token = tokens.popleft()
                if token == '(':
                    result = parse_expression(tokens)
                    if tokens.popleft() != ')':
                        raise ValueError("Mismatched parentheses")
                    return result
                elif token == '-':
                    return -parse_factor(tokens)
                else:
                    return int(token)

            result = parse_factor(tokens)
            while tokens and tokens[0] in ('*', '/'):
                op = tokens.popleft()
                right = parse_factor(tokens)
                if op == '*':
                    result *= right
                elif op == '/':
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    result = result // right if result * right >= 0 else -(abs(result) // abs(right))
            return result

        result = parse_term(tokens)
        while tokens and tokens[0] in ('+', '-'):
            op = tokens.popleft()
            right = parse_term(tokens)
            if op == '+':
                result += right
            elif op == '-':
                result -= right
        return result

    def parse_exponent(tokens):
        result = parse_term(tokens)
        while tokens and tokens[0] == '^':
            tokens.popleft()
            right = parse_exponent(tokens)
            result = result ** right
        return result

    tokens = deque(tokens)
    return parse_exponent(tokens)
