import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Attempt to parse the IP string
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return False  # Not a valid IP address

    # Check if the IP is public
    if isinstance(ip, ipaddress.IPv4Address):
        # Check for private, loopback, link-local, multicast, unspecified, reserved, or documentation ranges
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved:
            return False
        # Check for shared address space 100.64.0.0/10
        if ip.network_address <= ipaddress.IPv4Network('100.64.0.0/10').broadcast_address:
            return False
        # Check for IPv4 broadcast address
        if ip == ipaddress.IPv4Network('255.255.255.255/32').network_address:
            return False
        return True
    elif isinstance(ip, ipaddress.IPv6Address):
        # Check for private, loopback, link-local, multicast, unspecified, or documentation ranges
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_documentation:
            return False
        # Check for IPv4-mapped IPv6 address
        if ip.ipv4_mapped:
            return is_public_ip(str(ip.ipv4_mapped))
        return True
    return False
