def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    if capacity == 0:
        return ([], [])

    cache = {}
    access_order = []
    results = []

    for op in operations:
        if op[0] == "put":
            key = op[1]
            value = op[2]
            if key in cache:
                # Update existing key and move to most recently used
                cache[key] = value
                access_order.remove(key)
            else:
                # Add new key
                if len(cache) >= capacity:
                    # Remove least recently used (first in access_order)
                    lru_key = access_order.pop(0)
                    del cache[lru_key]
            access_order.append(key)
            cache[key] = value
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                # Move to most recently used
                access_order.remove(key)
                access_order.append(key)
                results.append(cache[key])
            else:
                results.append(None)

    # Return keys in order from least recently used to most recently used
    return (results, access_order)
