def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0  # instruction pointer
    instruction_count = 0

    while ip < len(program) and instruction_count < 1000:
        instruction = program[ip]
        instruction_count += 1

        if instruction.startswith("PUSH "):
            _, n = instruction.split()
            stack.append(int(n))
        elif instruction == "POP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.pop()
        elif instruction == "DUP":
            if not stack:
                raise ValueError("Stack underflow")
            stack.append(stack[-1])
        elif instruction == "SWAP":
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction.startswith("ADD"):
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a, b = stack[-2], stack[-1]
            stack.pop()
            stack.pop()
            stack.append(a + b)
        elif instruction.startswith("SUB"):
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a, b = stack[-2], stack[-1]
            stack.pop()
            stack.pop()
            stack.append(a - b)
        elif instruction.startswith("MUL"):
            if len(stack) < 2:
                raise ValueError("Stack underflow")
            a, b = stack[-2], stack[-1]
            stack.pop()
            stack.pop()
            stack.append(a * b)
        elif instruction.startswith("JMP "):
            _, t = instruction.split()
            ip = int(t)
        elif instruction.startswith("JZ "):
            _, t = instruction.split()
            t = int(t)
            if stack and stack[-1] == 0:
                ip = t
            else:
                ip += 1
        elif instruction == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        ip += 1

    if instruction_count >= 1000:
        raise RuntimeError("Too many instructions executed")

    return stack
