def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            # Update stock
            stock[item] = stock.get(item, 0) + quantity

            # Process waiting orders for this item
            while item in waiting and stock[item] >= waiting[item][0]:
                order_item, order_quantity = waiting[item][0]
                stock[item] -= order_quantity
                waiting[item].pop(0)

        elif kind == 'order':
            # Check if the item is in stock
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Add to waiting list
                if item not in waiting:
                    waiting[item] = []
                waiting[item].append((item, quantity))

    # Prepare the final waiting list, ordered by the time orders were placed
    waiting_list = []
    for item in waiting:
        waiting_list.extend(waiting[item])

    return (stock, waiting_list)
